def choose_move(observation):
    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0

    obstacles = set()
    for p in observation.get("obstacles") or []:
        x, y = pos(p, None) if p is not None else (None, None)
        if x is not None:
            obstacles.add((x, y))

    resources = []
    for r in observation.get("resources") or []:
        x, y = pos(r, None) if r is not None else (None, None)
        if x is not None:
            resources.append((x, y))

    cx = gw // 2 if gw else sx
    cy = gh // 2 if gh else sy

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    legal = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx, ny = sx + dx, sy + dy
            if gw and (nx < 0 or nx >= gw):
                continue
            if gh and (ny < 0 or ny >= gh):
                continue
            if (nx, ny) in obstacles:
                continue
            legal.append((dx, dy, nx, ny))

    if not legal:
        return [0, 0]

    nearest_res = None
    best_res_d = None
    for r in resources:
        d = manhattan((sx, sy), r)
        if best_res_d is None or d < best_res_d:
            best_res_d = d
            nearest_res = r

    opp_d = manhattan((sx, sy), (ox, oy))
    mode_flee = opp_d <= 3 and (not resources or best_res_d is None or opp_d <= best_res_d)

    best = None
    best_score = None
    for dx, dy, nx, ny in legal:
        score = 0

        if nearest_res is not None:
            dr = manhattan((nx, ny), nearest_res)
            score -= dr * 6
            score += (manhattan((sx, sy), nearest_res) - dr) * 2

        do = manhattan((nx, ny), (ox, oy))
        if mode_flee:
            score += do * 8
            score -= 10 if (nx, ny) == (ox, oy) else 0
        else:
            if opp_d <= 2:
                score += do * 2
            else:
                score += do

        dc = manhattan((nx, ny), (cx, cy))
        if not resources:
            score -= dc

        if (dx, dy) == (0, 0):
            score -= 1

        if mode_flee and dx == 0 and dy == 0:
            score -= 3

        if best_score is None or score > best_score or (score == best_score and (dx, dy) < (best[0], best[1])):
            best_score = score
            best = (dx, dy)

    return [best[0], best[1]]

